// ============ HELPER FUNCTIONS ============

const loadImageElement = (file) => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.onload = () => { URL.revokeObjectURL(url); resolve(img); };
    img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('Failed to load image')); };
    img.src = url;
  });
};

const analyzeColors = async (img) => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');

  const size = 150;
  canvas.width = size;
  canvas.height = size;
  ctx.drawImage(img, 0, 0, size, size);

  const imageData = ctx.getImageData(0, 0, size, size);
  const pixels = imageData.data;

  const colorMap = {};

  for (let i = 0; i < pixels.length; i += 16) {
    const r = pixels[i];
    const g = pixels[i + 1];
    const b = pixels[i + 2];
    const a = pixels[i + 3];

    if (a < 128) continue;

    const brightness = (r + g + b) / 3;
    if (brightness < 20 || brightness > 235) continue;

    // Quantize colors
    const qr = Math.round(r / 30) * 30;
    const qg = Math.round(g / 30) * 30;
    const qb = Math.round(b / 30) * 30;

    const key = `${qr},${qg},${qb}`;
    colorMap[key] = (colorMap[key] || 0) + 1;
  }

  return Object.entries(colorMap)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 4)
    .map(([rgb]) => {
      const [r, g, b] = rgb.split(',').map(Number);
      return getColorName(r, g, b);
    })
    .filter((c, i, arr) => arr.indexOf(c) === i);
};

const getColorName = (r, g, b) => {
  const brightness = (r + g + b) / 3;

  if (brightness < 40) return 'black';
  if (brightness > 200) return 'white';

  const max = Math.max(r, g, b);
  const min = Math.min(r, g, b);
  const saturation = max === 0 ? 0 : (max - min) / max;

  if (saturation < 0.1) {
    if (brightness < 80) return 'dark gray';
    if (brightness < 150) return 'gray';
    return 'light gray';
  }

  let hue = 0;
  if (max === r) hue = ((g - b) / (max - min)) % 6;
  else if (max === g) hue = (b - r) / (max - min) + 2;
  else hue = (r - g) / (max - min) + 4;

  hue = (hue * 60 + 360) % 360;

  if (hue < 15 || hue >= 345) return 'red';
  if (hue < 45) return 'orange';
  if (hue < 65) return 'yellow';
  if (hue < 150) return 'green';
  if (hue < 200) return 'cyan';
  if (hue < 260) return 'blue';
  if (hue < 290) return 'purple';
  if (hue < 330) return 'magenta';
  return 'pink';
};

const detectEdges = async (img) => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = 100;
  canvas.height = 100;
  ctx.drawImage(img, 0, 0, 100, 100);

  const imageData = ctx.getImageData(0, 0, 100, 100);
  const data = imageData.data;

  let edges = 0;
  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    const gray = (r + g + b) / 3;

    if (i > 404 && i < data.length - 404) {
      const neighbors = [data[i - 404], data[i - 400], data[i - 396]];
      const diff = Math.abs(gray - (neighbors[1] / 3));
      if (diff > 30) edges++;
    }
  }

  return edges > 100;
};

const detectPatterns = async (img) => {
  const canvas = document.createElement('canvas');
  const ctx = canvas.getContext('2d');
  canvas.width = 50;
  canvas.height = 50;
  ctx.drawImage(img, 0, 0, 50, 50);

  const imageData = ctx.getImageData(0, 0, 50, 50);
  const data = imageData.data;

  let variance = 0;
  for (let i = 0; i < data.length - 4; i += 4) {
    variance += Math.abs(data[i] - data[i + 4]);
  }

  return variance / (data.length / 4);
};

const generateItemHints = (colors, hasEdges, patternVariance, width, height) => {
  const ratio = width / height;
  let hints = { likelyType: 'Item', likelyMaterial: 'Unknown', details: '' };

  // Check for shiny/glossy (typical of phones, watches)
  const hasShiny = colors.includes('black') || colors.includes('white') || colors.includes('silver');

  // Check for metallic
  const isMetallic = colors.some(c => ['silver', 'gold', 'rose gold', 'bronze', 'copper'].includes(c));

  // Shape analysis
  if (ratio > 0.4 && ratio < 0.7) {
    hints.likelyType = 'Smartphone or tablet';
    if (hasShiny) hints.likelyMaterial = 'Glass and aluminum';
  } else if (ratio > 0.6 && ratio < 1.2) {
    hints.likelyType = 'Wallet, small bag, or notebook';
    if (colors.includes('brown') || colors.includes('tan')) hints.likelyMaterial = 'Leather';
  }

  if (isMetallic && !hasShiny) {
    hints.likelyType = 'Jewelry or watch';
    hints.likelyMaterial = 'Metal';
  }

  return hints;
};

