// ============ FIXED AUTOFILL FUNCTION - NOW INCLUDES ALL FIELDS ============
export const autoFillFormFromDescription = (aiResponse) => {
  if (!aiResponse?.structured) return null;

  const s = aiResponse.structured;
  const parts = [];

  // Build item name from available fields
  if (s.colors && s.colors !== 'Unknown' && s.colors !== 'See image') {
    const firstColor = s.colors.split(',')[0].trim();
    if (firstColor) parts.push(firstColor);
  }

  if (s.brand && s.brand !== 'Unknown' && s.brand !== 'Not visible' && s.brand !== 'Not detected') {
    parts.push(s.brand);
  }

  if (s.material && 
      s.material !== 'Unknown' && 
      s.material !== 'Unable to detect - please specify') {
    parts.push(s.material);
  }

  if (s.itemType && s.itemType !== 'Unknown') {
    parts.push(s.itemType);
  }

  // Build enhanced description that includes ALL structured fields
  let enhancedDescription = '';

  // Start with item type and material if available
  if (s.itemType && s.itemType !== 'Unknown' && s.itemType !== 'Unable to identify') {
    enhancedDescription = s.itemType;

    // Add material if it's meaningful and different from item type
    if (s.material && 
        s.material !== 'Unknown' && 
        s.material !== 'Unable to detect - please specify' &&
        s.material.toLowerCase() !== s.itemType.toLowerCase()) {
      enhancedDescription += ` (Material: ${s.material})`;
    }
  }

  // Build structured details section
  const details = [];

  if (s.colors && s.colors !== 'Unknown' && s.colors !== 'See image') {
    details.push(`Colors: ${s.colors}`);
  }

  if (s.brand && s.brand !== 'Unknown' && s.brand !== 'Not visible' && s.brand !== 'Not detected') {
    details.push(`Brand: ${s.brand}`);
  }

  if (s.material && 
      s.material !== 'Unknown' && 
      s.material !== 'Unable to detect - please specify' &&
      !enhancedDescription.includes(s.material)) {
    details.push(`Material: ${s.material}`);
  }

  if (s.condition && 
      s.condition !== 'Unknown' && 
      s.condition !== 'Unable to detect - please specify') {
    details.push(`Condition: ${s.condition}`);
  }

  if (s.features && 
      s.features !== 'N/A' && 
      s.features !== 'Unknown' && 
      s.features !== 'Unable to detect - please specify') {
    details.push(`Distinctive Features: ${s.features}`);
  }

  // Combine structured details
  if (details.length > 0) {
    enhancedDescription += '\n\n' + details.join('. ') + '.';
  }

  // Add the natural description from Gemini if it's meaningful
  if (aiResponse.naturalDescription && 
      aiResponse.naturalDescription !== 'Item details not detected - please add manually.' &&
      !aiResponse.naturalDescription.includes('Please provide additional details')) {
    // Avoid duplication - only add if natural description has different content
    const naturalDesc = aiResponse.naturalDescription.trim();
    if (!enhancedDescription.includes(naturalDesc.substring(0, 50))) {
      enhancedDescription += '\n\n' + naturalDesc;
    }
  }

  // Fallback if nothing was generated
  if (!enhancedDescription.trim()) {
    enhancedDescription = aiResponse.naturalDescription || 'Item details not detected - please add manually.';
  }

  return {
    itemName: parts.join(' ').trim() || 'Found Item',
    description: enhancedDescription.trim()
  };
};
